# donetoast card: a Steam-style (2023+) notification card.
#   283x70, sits right on the taskbar flush with the right screen edge, stacked cards have no gaps,
#   slides up in 300 ms with cubic-bezier(0,.73,.48,1) (Steam's own curve).
#   Plays done.wav / failed.wav / waiting.wav (generated by make-sounds.ps1). Works even when Windows notifications are off.
# Usage: toast.ps1 -Title "Render finished" -Message "frame_12.png ready" [-Failed | -Waiting] [-Seconds 20]
#   Click to dismiss. -Seconds closes it automatically after that many seconds (0 = stays until clicked).
#   -App: source name in the header (Claude, Codex, ...). -Icon: 44 px image (default: icons\<app>.png, else icon.png).
#   -Id <name>: live card. It follows progress\<name>.json (written by donetoast.ps1 -Id), shows a progress bar
#     and an estimate of the time left, and turns into a done / failed card when the job ends. Deleting the file closes it.
#   -Preview <folder>: render PNG frames off-screen instead of opening a window (README images); -PreviewY = vertical offset per frame.
#     -State running -Percent 42 draws a progress card in preview mode.
param(
  [string]$Title = 'Job finished',
  [string]$Message = '',
  [switch]$Failed,
  [switch]$Waiting,
  [string]$Id = '',
  [int]$Seconds = 0,
  [string]$App = 'Claude',
  [string]$Icon = '',
  [string]$Time = '',
  [string]$Preview = '',
  [double[]]$PreviewY = @(0),
  [string]$State = '',
  [double]$Percent = -1
)

Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase

# Current content: title, message, percent (-1 = unknown) and state (done | failed | waiting | running)
$script:cur = @{ title = $Title; message = $Message; percent = $Percent
                 state = if ($State) { $State } elseif ($Failed) { 'failed' } elseif ($Waiting) { 'waiting' } else { 'done' } }
$dir = "$PSScriptRoot\progress"
$file = if ($Id) { "$dir\$Id.json" } else { $null }
$script:lw = [datetime]::MinValue; $script:seen = $false
$script:t0 = Get-Date; $script:p0 = $null; $script:tp = $null
function Apply($j) {
  if ($null -ne $j.title)   { $script:cur.title = [string]$j.title }
  if ($null -ne $j.message) { $script:cur.message = [string]$j.message }
  if ($null -ne $j.state)   { $script:cur.state = [string]$j.state }
  if ($null -ne $j.app -and $j.app) { $script:App = [string]$j.app }
  if ($null -ne $j.percent) {
    $p = [double]$j.percent
    if ($p -ge 0 -and $p -ne $script:cur.percent) {
      if ($null -eq $script:p0) { $script:p0 = @{ p = $p; t = Get-Date } }
      $script:tp = Get-Date
    }
    $script:cur.percent = $p
  }
}
function ReadState {   # $true when the file changed and was read
  $t = [IO.File]::GetLastWriteTimeUtc($file)
  if ($t -eq $script:lw) { return $false }
  try { $j = [IO.File]::ReadAllText($file) | ConvertFrom-Json } catch { return $false }   # half-written: next tick
  $script:lw = $t; $script:seen = $true; Apply $j; $true
}
if ($file) {
  if (-not (Test-Path -LiteralPath $file)) { return }   # already finished or dismissed: nothing to show
  ReadState | Out-Null
}

if (-not $Preview) { Add-Content -Encoding UTF8 "$PSScriptRoot\toast.log" "$(Get-Date -Format s) [$($script:cur.state)] $($script:cur.title) | $($script:cur.message)" }

# Stacking: take the first free slot (slots stack upward from the taskbar with no gaps)
$mutex = $null; $slot = 0
if (-not $Preview) {
  for ($i = 0; $i -lt 8; $i++) {
    $m = New-Object Threading.Mutex($false, "Local\DonetoastSlot$i")
    $got = $false
    try { $got = $m.WaitOne(0) } catch [Threading.AbandonedMutexException] { $got = $true }
    if ($got) { $mutex = $m; $slot = $i; break }
    $m.Dispose()
  }
}

# accent, Segoe Fluent glyph, header word, sound
$looks = @{
  done    = @('#91C257', 0xE73E, 'done',      'done.wav')
  failed  = @('#E5604F', 0xE7BA, 'failed',    'failed.wav')
  waiting = @('#E8B04B', 0xE8BD, 'needs you', 'waiting.wav')
  running = @('#1A9FFF', 0xE916, 'running',   $null)
}
if (-not $Icon) { $Icon = "$PSScriptRoot\icons\$($App.ToLowerInvariant()).png"; if (-not (Test-Path $Icon)) { $Icon = "$PSScriptRoot\icon.png" } }

[xml]$xaml = @"
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        WindowStyle="None" AllowsTransparency="True" Background="Transparent"
        Topmost="True" ShowInTaskbar="False" ShowActivated="False" ResizeMode="NoResize"
        Width="283" Height="70" Cursor="Hand" UseLayoutRounding="True" SnapsToDevicePixels="True"
        FontFamily="Segoe UI Variable Text, Segoe UI"
        TextOptions.TextFormattingMode="Display" TextOptions.TextRenderingMode="ClearType">
  <Grid ClipToBounds="True" Width="283" Height="70">
    <Grid x:Name="Card">
      <Grid.RenderTransform><TranslateTransform x:Name="Slide" Y="70"/></Grid.RenderTransform>
      <Grid.Background>
        <RadialGradientBrush GradientOrigin="0,0" Center="0,0" RadiusX="1.5542" RadiusY="1">
          <GradientStop Color="#23262E" Offset="0"/>
          <GradientStop Color="#0E141B" Offset="1"/>
        </RadialGradientBrush>
      </Grid.Background>

      <Border x:Name="Glow" Opacity="0" IsHitTestVisible="False">
        <Border.Background>
          <RadialGradientBrush GradientOrigin="0,0" Center="0,0" RadiusX="1.5542" RadiusY="1">
            <GradientStop Color="#1F2A39" Offset="0"/>
            <GradientStop Color="#531AA0FF" Offset="1"/>
          </RadialGradientBrush>
        </Border.Background>
      </Border>

      <!-- 1 px top line separates stacked cards (instead of a gap) -->
      <Border Height="1" VerticalAlignment="Top" Background="#14FFFFFF" IsHitTestVisible="False"/>

      <!-- Steam: padding 10, avatar 44, text 12 px after the avatar -->
      <Grid Margin="10,8,10,8">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="44"/><ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>
        <Image x:Name="Avatar" Width="44" Height="44" RenderOptions.BitmapScalingMode="HighQuality"/>
        <Grid Grid.Column="1" Margin="12,0,0,0" VerticalAlignment="Center">
          <Grid.RowDefinitions><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/><RowDefinition Height="Auto"/></Grid.RowDefinitions>
          <DockPanel>
            <TextBlock x:Name="Clock" DockPanel.Dock="Right" FontSize="11" Foreground="#67707B" Margin="6,0,0,0"/>
            <TextBlock FontSize="11" FontWeight="Medium" Foreground="#8B929A" TextTrimming="CharacterEllipsis">
              <Run x:Name="Glyph" FontFamily="Segoe Fluent Icons, Segoe MDL2 Assets" FontSize="10" BaselineAlignment="Center"/>
              <Run x:Name="Header"/>
            </TextBlock>
          </DockPanel>
          <TextBlock x:Name="TitleText" Grid.Row="1" FontSize="13" FontWeight="SemiBold" Foreground="#FFFFFF"
                     TextTrimming="CharacterEllipsis" Margin="0,1,0,0"/>
          <TextBlock x:Name="MessageText" Grid.Row="2" FontSize="11.5" Foreground="#8B929A"
                     TextTrimming="CharacterEllipsis" Margin="0,1,0,0"/>
        </Grid>
      </Grid>

      <!-- progress: 2 px bar along the bottom edge -->
      <Border x:Name="Track" Height="2" VerticalAlignment="Bottom" Background="#12FFFFFF" Visibility="Collapsed" IsHitTestVisible="False">
        <Border x:Name="Bar" HorizontalAlignment="Left" Width="0"/>
      </Border>
    </Grid>
  </Grid>
</Window>
"@

$w = [Windows.Markup.XamlReader]::Load((New-Object System.Xml.XmlNodeReader $xaml))
$el = @{}; foreach ($n in 'Card', 'Slide', 'Glow', 'Glyph', 'Header', 'Clock', 'TitleText', 'MessageText', 'Avatar', 'Track', 'Bar') { $el[$n] = $w.FindName($n) }

# Load the icon fully into memory (no file lock, ready immediately in preview mode too)
$bi = New-Object Windows.Media.Imaging.BitmapImage
$bi.BeginInit(); $bi.CacheOption = 'OnLoad'; $bi.DecodePixelWidth = 88; $bi.UriSource = [Uri]$Icon; $bi.EndInit(); $bi.Freeze()
$el.Avatar.Source = $bi
$el.Clock.Text = if ($Time) { $Time } else { Get-Date -Format 'HH:mm' }

$spline = New-Object Windows.Media.Animation.KeySpline(0, 0.73, 0.48, 1)
function Animate($target, $prop, $to, $ms, $onDone) {
  $a = New-Object Windows.Media.Animation.DoubleAnimationUsingKeyFrames
  $a.KeyFrames.Add((New-Object Windows.Media.Animation.SplineDoubleKeyFrame($to, [Windows.Media.Animation.KeyTime]::FromTimeSpan([TimeSpan]::FromMilliseconds($ms)), $spline))) | Out-Null
  if ($onDone) { $a.add_Completed($onDone) }
  $target.BeginAnimation($prop, $a)
}

function Fmt([TimeSpan]$s) {
  if ($s.TotalHours -ge 1) { '{0} h {1} min' -f [int][Math]::Floor($s.TotalHours), $s.Minutes }
  elseif ($s.TotalMinutes -ge 1) { '{0} min' -f [int][Math]::Round($s.TotalMinutes) }
  else { '{0} s' -f [int][Math]::Max(1, [Math]::Round($s.TotalSeconds)) }
}
# Second line of a live running card: "42% · 8 min left · <message>"
function RunText {
  $c = $script:cur; $now = Get-Date; $parts = @()
  if ($c.percent -ge 0) {
    $parts += '{0}%' -f [int][Math]::Floor($c.percent)
    if ($script:p0 -and $c.percent -gt $script:p0.p -and $c.percent -lt 100) {
      $dt = ($script:tp - $script:p0.t).TotalSeconds
      if ($dt -ge 2) {
        $left = $dt * (100 - $c.percent) / ($c.percent - $script:p0.p) - ($now - $script:tp).TotalSeconds
        $parts += if ($left -ge 1) { "$(Fmt ([TimeSpan]::FromSeconds($left))) left" } else { 'almost done' }
      }
    }
  } else { $parts += "$(Fmt ($now - $script:t0)) elapsed" }
  if ($c.message) { $parts += $c.message }
  $parts -join ' · '
}
function SetBar([double]$p, [bool]$animate) {
  $p = [Math]::Min(100, [Math]::Max(0, $p)); $width = 283 * $p / 100
  if ($animate) { Animate $el.Bar ([Windows.FrameworkElement]::WidthProperty) $width 400 $null }
  else { $el.Bar.BeginAnimation([Windows.FrameworkElement]::WidthProperty, $null); $el.Bar.Width = $width }
}
function ShowState([bool]$animate) {
  $c = $script:cur; $l = $looks[$c.state]; if (-not $l) { $l = $looks.done }
  $brush = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString($l[0])); $brush.Freeze()
  $el.Glyph.Text = [string][char]$l[1]; $el.Glyph.Foreground = $brush; $el.Bar.Background = $brush
  $el.Header.Text = " $script:App  ·  $($l[2])"
  $el.TitleText.Text = $c.title
  $el.MessageText.Text = if ($c.state -eq 'running' -and $Id) { RunText } else { $c.message }
  if ($c.percent -ge 0 -or ($c.state -eq 'running' -and $Id)) {
    $el.Track.Visibility = 'Visible'
    SetBar $(if ($c.state -eq 'done') { 100 } else { [Math]::Max(0, $c.percent) }) $animate
  }
  $w.ToolTip = if ($el.MessageText.Text) { "$($c.title)`n$($el.MessageText.Text)" } else { $c.title }
}
ShowState $false

# Preview: write frames as 2x PNGs without opening a window, then exit
if ($Preview) {
  New-Item -ItemType Directory -Force $Preview | Out-Null
  $root = $w.Content; $w.Content = $null
  $root.Measure([Windows.Size]::new(283, 70)); $root.Arrange([Windows.Rect]::new(0, 0, 283, 70))
  for ($k = 0; $k -lt $PreviewY.Count; $k++) {
    $el.Slide.Y = $PreviewY[$k]; $root.UpdateLayout()
    $rtb = New-Object Windows.Media.Imaging.RenderTargetBitmap(566, 140, 192, 192, [Windows.Media.PixelFormats]::Pbgra32)
    $rtb.Render($root)
    $enc = New-Object Windows.Media.Imaging.PngBitmapEncoder; $enc.Frames.Add([Windows.Media.Imaging.BitmapFrame]::Create($rtb))
    $fs = [IO.File]::Create((Join-Path $Preview ('frame{0:D3}.png' -f $k))); $enc.Save($fs); $fs.Close()
  }
  return
}

function Play($state) {
  $s = $looks[$state]; if ($s -and $s[3]) { try { (New-Object Media.SoundPlayer "$PSScriptRoot\$($s[3])").Play() } catch {} }
}
# Release memory once so the waiting card stays small (~140 MB -> ~10 MB working set)
function TrimNow {
  [GC]::Collect(); [GC]::WaitForPendingFinalizers(); [GC]::Collect()
  # One-off trim: drop the working-set limit to the minimum and restore it right away (a permanent cap costs CPU)
  try { $p = [Diagnostics.Process]::GetCurrentProcess(); $oldMax = $p.MaxWorkingSet
        $p.MaxWorkingSet = [IntPtr]$p.MinWorkingSet; $p.MaxWorkingSet = $oldMax } catch {}
}
function TrimSoon {
  $t = New-Object Windows.Threading.DispatcherTimer -Property @{ Interval = [TimeSpan]::FromSeconds(2) }
  $t.add_Tick({ $this.Stop(); TrimNow }); $t.Start()
}

$script:closing = $false
$close = {
  if ($script:closing) { return }; $script:closing = $true
  if ($script:poll) { $script:poll.Stop() }
  Animate $el.Slide ([Windows.Media.TranslateTransform]::XProperty) 283 260 { $w.Close() }
}

# Live card: poll the state file once a second (a file-time check; the file is only read when it changed)
$script:poll = $null
function Finish {
  $script:poll.Stop(); $script:poll = $null
  if ($script:cur.state -eq 'done' -and -not $script:cur.message) {
    $script:cur.message = "Took $(Fmt ((Get-Date) - $script:t0))"; ShowState $true
  }
  Remove-Item -LiteralPath $file, "$dir\$Id.muted" -Force -ErrorAction SilentlyContinue
  TrimSoon
}
if ($Id) {
  $script:poll = New-Object Windows.Threading.DispatcherTimer -Property @{ Interval = [TimeSpan]::FromSeconds(1) }
  $script:ticks = 0
  $script:poll.add_Tick({
    if (-not (Test-Path -LiteralPath $file)) { if ($script:seen) { & $close }; return }   # dismissed
    if ((++$script:ticks % 30) -eq 0) { TrimNow }   # a long-lived card keeps its memory small
    $before = $script:cur.state
    if (ReadState) {
      ShowState $true
      $now = $script:cur.state
      if ($now -eq 'waiting' -or ($now -ne $before -and $now -ne 'running')) { Play $now }
      if ($now -eq 'done' -or $now -eq 'failed') { Finish }
    } elseif ($script:cur.state -eq 'running') { $el.MessageText.Text = RunText }
  })
}

$w.add_MouseLeftButtonUp({
  if ($Id -and $script:poll) {
    # Running job: hide this card but keep following it; a new card shows up when it ends. Anything else: dismiss.
    if ($script:cur.state -eq 'running') { New-Item -ItemType File -Force "$dir\$Id.muted" | Out-Null }
    else { Remove-Item -LiteralPath $file -Force -ErrorAction SilentlyContinue }
  }
  & $close
})
$w.add_MouseEnter({ $el.Glow.BeginAnimation([Windows.UIElement]::OpacityProperty, (New-Object Windows.Media.Animation.DoubleAnimation(0.5, [Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))))) })
$w.add_MouseLeave({ $el.Glow.BeginAnimation([Windows.UIElement]::OpacityProperty, (New-Object Windows.Media.Animation.DoubleAnimation(0, [Windows.Duration]::new([TimeSpan]::FromMilliseconds(300))))) })

$w.add_ContentRendered({
  $area = [Windows.SystemParameters]::WorkArea
  $w.Left = $area.Right - 283
  $w.Top = $area.Bottom - 70 * ($slot + 1)
  Animate $el.Slide ([Windows.Media.TranslateTransform]::YProperty) 0 300 $null
  Play $script:cur.state
  TrimSoon
  if ($script:poll) {
    if ($script:cur.state -eq 'done' -or $script:cur.state -eq 'failed') { Finish } else { $script:poll.Start() }
  }
  if ($Seconds -gt 0) {
    $t = New-Object Windows.Threading.DispatcherTimer -Property @{ Interval = [TimeSpan]::FromSeconds($Seconds) }
    $t.add_Tick({ $this.Stop(); & $close }); $t.Start()
  }
})

$w.Left = -10000; $w.Top = -10000
$w.add_Closed({
  if ($Id) {   # donetoast.ps1 uses the pid file to tell whether this card is still open
    $pf = "$dir\$Id.pid"
    try { if ((Get-Content -LiteralPath $pf -ErrorAction Stop) -eq "$PID") { Remove-Item -LiteralPath $pf -Force } } catch {}
  }
  $w.Dispatcher.InvokeShutdown()
})
$w.Show()
[Windows.Threading.Dispatcher]::Run()

if ($mutex) { try { $mutex.ReleaseMutex() } catch {}; $mutex.Dispose() }
